package org.usbworkbench;
import java.io.*;import java.util.*;
public class NativeBridgeTest{
 public static void main(String[] args)throws Exception{File path=new File("artifacts/native-bridge-owned.img");int checks=0;for(boolean ro:new boolean[]{false,true})try(NativeIntegrationTest.Image disk=new NativeIntegrationTest.Image(path,64L*1048576)){ProcessBuilder b=new ProcessBuilder(new File("artifacts/native-bridge-probe").getAbsolutePath());if(ro)b.command().add("readonly");Map<String,String> env=b.environment();env.remove("LD_LIBRARY_PATH");env.put("LD_PRELOAD",new File("app/src/main/jniLibs/arm64-v8a/libusbwb_bridge.so").getAbsolutePath());env.put("USBWB_BYTES",Long.toString(64L*1048576));env.put("USBWB_WRITE",ro?"0":"1");Process child=b.start();NativeProtocol.serve(child.getInputStream(),child.getOutputStream(),disk,!ro,(a,n)->{});if(child.waitFor()!=0)throw new AssertionError("Bridge probe failed: "+child.exitValue());checks+=15;}finally{path.delete();}System.out.println("PASS: "+checks+" native multi-open independent offsets/bounds/access-mode/global-read-only/close/reuse/handle-limit checks");}}
